const data = $input.first().json;
const stats = data.stats || [];
const active = stats.filter(s => s.status === 'active');
const paused = stats.filter(s => s.status === 'paused');
const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const topCountries = [...stats].sort((a, b) => b.clicks - a.clicks).slice(0, 5);
const topLines = topCountries.map((s, i) => `${i+1}. ${s.country.name}: ${s.clicks} clicks / ${s.conversions} conv`).join('\n');

const report = [
  `📅 *Rapport Journalier InterviewPro*`,
  `${date}`,
  ``,
  `🌍 *Pipelines:* ${active.length} actifs | ${paused.length} en pause`,
  `📊 *Total:* ${data.total.clicks} clicks | ${data.total.conversions} conversions`,
  ``,
  `🏆 *Top 5 pays:*`,
  topLines || 'Aucune donnée',
  ``,
  `_Rapport automatique InterviewPro v2_`
].join('\n');

return [{ json: { report } }];
